const journalTokenState = `-- name: JournalTokenState :many

SELECT t.id::text AS id, t.type, (t.revoked_at IS NOT NULL)::boolean AS revoked
  FROM api_token t WHERE t.id = $1::text::uuid
`

type JournalTokenStateRow struct {
	ID      string
	Type    string
	Revoked bool
}

// Queries of the revocation journal's replay handlers (R-HA-054, R-AUTHZ-031, R-AUTH-041; the handlers are the
// journal_replay.go files of internal/auth/token, internal/auth/principal, internal/authz and internal/project, and the
// restore's clean-up in internal/journal/replay). A replay changes the restored database only by removing or narrowing, and it
// names every object by its ID, so these statements take IDs, never names.
// The state of a token of any type (the token API's IdentityTokenRow leaves out Bastion tokens, which a replay must revoke
// as well). No row: the token is not in the restored database.
func (q *Queries) JournalTokenState(ctx context.Context, id string) ([]JournalTokenStateRow, error) {
	rows, err := q.db.Query(ctx, journalTokenState, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []JournalTokenStateRow{}
	for rows.Next() {
		var i JournalTokenStateRow
		if err := rows.Scan(&i.ID, &i.Type, &i.Revoked); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const journalUnsuppressBinding = `-- name: JournalUnsuppressBinding :exec
UPDATE system_state
   SET value = COALESCE((SELECT jsonb_agg(to_jsonb(e)) FROM jsonb_array_elements_text(system_state.value) e WHERE e <> $1::text), '[]'::jsonb),
       updated_at = now()
 WHERE key = 'journal_suppressed_bindings' AND jsonb_exists(value, $1::text)
`

func (q *Queries) JournalUnsuppressBinding(ctx context.Context, entry string) error {
	_, err := q.db.Exec(ctx, journalUnsuppressBinding, entry)
	return err
}

const journalUserState = `-- name: JournalUserState :many
SELECT p.kind, p.status, coalesce(u.is_break_glass, false)::boolean AS is_break_glass
  FROM principal p LEFT JOIN app_user u ON u.principal_id = p.id
 WHERE p.id = $1::text::uuid
`

type JournalUserStateRow struct {
	Kind         string
	Status       string
	IsBreakGlass bool
}

// The user behind a principal, to tell a disabled user from a disabled break-glass account.
func (q *Queries) JournalUserState(ctx context.Context, id string) ([]JournalUserStateRow, error) {
	rows, err := q.db.Query(ctx, journalUserState, id)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []JournalUserStateRow{}
	for rows.Next() {
		var i JournalUserStateRow
		if err := rows.Scan(&i.Kind, &i.Status, &i.IsBreakGlass); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
